from docx import Document

PATH = '/home/user/Desktop/Geography_And_Magical_Realism.docx'

def capitalize_para(para):
    prev_boundary = True
    for run in para.runs:
        new_chars = []
        for ch in run.text:
            if ch.isalpha():
                if prev_boundary:
                    new_chars.append(ch.upper())
                else:
                    new_chars.append(ch)
                prev_boundary = False
            else:
                new_chars.append(ch)
                prev_boundary = True
        run.text = ''.join(new_chars)

doc = Document(PATH)

for para in doc.paragraphs:
    capitalize_para(para)

for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                capitalize_para(para)

for section in doc.sections:
    for hf in (section.header, section.footer, section.first_page_header,
               section.first_page_footer, section.even_page_header,
               section.even_page_footer):
        for para in hf.paragraphs:
            capitalize_para(para)

doc.save(PATH)
print("done")

